let credentials=[],query='' ,winFilter='All',certFilter='All';const match=x=>JSON.stringify(x).toLowerCase().includes(query);
function render(){const ps=projects.filter(match);$('#projectRow').innerHTML=ps.map(p=>`<button class="project" data-project="${projects.indexOf(p)}" aria-label="Explore ${p.title}"><div class="poster"><img src="${p.image}" alt="" loading="lazy"><small>R · ORIGINAL</small><span class="poster-title">${p.title}</span></div><div class="project-info"><strong>${p.badge}</strong><p>${p.subtitle}</p><div class="tags"><span>${p.type}</span><span>Explore ↗</span></div></div></button>`).join('');$('#noProjects').hidden=ps.length>0;document.querySelectorAll('[data-project]').forEach(b=>b.onclick=()=>openProject(projects[+b.dataset.project]));const ws=wins.filter(w=>(winFilter==='All'||w.type===winFilter)&&match(w));$('#wins').innerHTML=ws.map(w=>`<article class="win">${winMedia[w.title]?`<div class="win-photo"><img src="assets/win-${winMedia[w.title][0]}.png" alt="${w.title} team achievement photo" loading="lazy"></div>`:""}<div class="win-body"><span class="type">${w.type.toUpperCase()}</span><span class="rank">${w.rank}</span><h3>${w.title}</h3><p>${w.host}</p><a href="${w.source}" target="_blank" rel="noopener">View source announcement ↗</a>${winMedia[w.title]?`<button class="evidence" data-evidence="${w.title}">View supplied evidence ↗</button>`:""}</div></article>`).join('')||'<p>No matching results.</p>';let cs=credentials.filter(c=>(certFilter==='All'||c.category===certFilter)&&match(c));if($('#sort').value==='title')cs.sort((a,b)=>a.title.localeCompare(b.title));$('#certCount').textContent=`${cs.length} IN THE COLLECTION`;$('#certs').innerHTML=cs.map(c=>`<article class="cert"><img src="${c.image}" alt="${c.title} certificate preview" loading="lazy"><section><h3>${c.title}</h3><p>${c.issuer}<br>${c.date}</p><a href="${c.file}" target="_blank" rel="noopener">View original certificate ↗</a></section></article>`).join('');$('#noCerts').hidden=cs.length>0;document.querySelectorAll('[data-evidence]').forEach(b=>b.onclick=()=>{const name=b.dataset.evidence;show(`<div class="dialog-body"><p class="kicker">SUPPLIED ANNOUNCEMENT</p><h2>${name}</h2><p>Original screenshots provided by Rishit. Dates shown are announcement dates unless the post explicitly states an event date.</p>${winMedia[name].map(n=>`<img class="evidence-image" src="assets/win-${n}.png" alt="Original ${name} announcement"><a class="text-link" href="assets/win-${n}.png" target="_blank" rel="noopener">Open original image ↗</a>`).join('')}</div>`)})}

function show(html){$('#dialogContent').innerHTML=html;$('#detail').showModal()}function openProject(p){show(`<img src="${p.image}" alt="Illustrative project artwork"><div class="dialog-body"><p class="kicker">${p.type}</p><h2>${p.title}</h2><strong>${p.badge}</strong><p>${p.description}</p><p>Collaborative team project. Specific individual contributions and technical details will be added with the repository.</p><a class="btn primary" href="${p.source}" target="_blank" rel="noopener">Read the announcement ↗</a>${p.repo?`<a class="btn secondary" href="${p.repo}" target="_blank" rel="noopener">View repository ↗</a>`:'<div class="pending">Repository link will be added soon.</div>'}</div>`)}
$('#closeDetail').onclick=()=>$('#detail').close();$('#detail').addEventListener('click',e=>{if(e.target===$('#detail')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}});$('#story').onclick=()=>show('<div class="dialog-body"><p class="kicker">THE PERSON BEHIND THE PROJECTS</p><h2>Hi, I’m Rishit.</h2><p>An AI & Data Science student at Dwarkadas J. Sanghvi College of Engineering and a member of Team Outliers. My work brings together technology, creative problem-solving and collaboration.</p><p>Explore the projects, competition results and learning journey in this collection.</p><a class="btn primary" href="'+profile+'" target="_blank" rel="noopener">Visit LinkedIn ↗</a></div>');
for(const [id,set] of [['winFilters',v=>winFilter=v],['certFilters',v=>certFilter=v]])document.querySelectorAll('#'+id+' button').forEach(b=>b.onclick=()=>{set(b.dataset.filter);b.parentElement.querySelectorAll('button').forEach(x=>x.classList.toggle('active',x===b));render()});$('#sort').onchange=render;$('#searchToggle').onclick=()=>{$('#searchPanel').hidden=!$('#searchPanel').hidden;if(!$('#searchPanel').hidden)$('#search').focus()};$('#search').oninput=e=>{query=e.target.value.trim().toLowerCase();render()};$('#clearSearch').onclick=()=>{$('#search').value='';query='';render();$('#search').focus()};document.addEventListener('keydown',e=>{if(e.key==='Escape')$('#searchPanel').hidden=true});document.querySelectorAll('[data-scroll]').forEach(b=>b.onclick=()=>$('#projectRow').scrollBy({left:+b.dataset.scroll*$('#projectRow').clientWidth*.8,behavior:paused?'instant':'smooth'}));
fetch('credentials.json').then(r=>{if(!r.ok)throw Error();return r.json()}).then(d=>{credentials=d;render()}).catch(()=>{$('#certs').textContent='Credentials could not load. Please refresh the page.'});render();
const canvas=$('#scene'),ctx=canvas.getContext('2d');let w,h,frame=0,paused=matchMedia('(prefers-reduced-motion: reduce)').matches;function resize(){const d=Math.min(devicePixelRatio,2);w=canvas.clientWidth;h=canvas.clientHeight;canvas.width=w*d;canvas.height=h*d;ctx.setTransform(d,0,0,d,0,0)}addEventListener('resize',resize);resize();const pts=Array.from({length:160},(_,i)=>{const y=1-i/79.5;const r=Math.sqrt(1-y*y);const a=i*2.399963;return{x:Math.cos(a)*r,y,z:Math.sin(a)*r}});function draw(){frame++;ctx.clearRect(0,0,w,h);const t=frame*.002;const cx=w*.75,cy=h*.46,s=Math.min(w*.27,h*.38);const projected=pts.map(p=>{const x=p.x*Math.cos(t)+p.z*Math.sin(t),z=p.z*Math.cos(t)-p.x*Math.sin(t);return{x:cx+x*s*(1+z*.13),y:cy+p.y*s*.94,z}});const glow=ctx.createRadialGradient(cx,cy,0,cx,cy,s*1.5);glow.addColorStop(0,'#39213e');glow.addColorStop(.55,'#142337');glow.addColorStop(1,'#090b13');ctx.fillStyle=glow;ctx.fillRect(0,0,w,h);projected.forEach((p,i)=>{projected.slice(i+1).forEach(q=>{const d=Math.hypot(p.x-q.x,p.y-q.y);if(d<s*.23){ctx.strokeStyle=`rgba(${p.z>0?'222,52,80':'83,132,174'},${(1-d/(s*.23))*(p.z+1.4)*.25})`;ctx.lineWidth=.7;ctx.beginPath();ctx.moveTo(p.x,p.y);ctx.lineTo(q.x,q.y);ctx.stroke()}});ctx.fillStyle=p.z>.3?'#f16b80':'#58758e';ctx.globalAlpha=(p.z+1.5)/2.5;ctx.beginPath();ctx.arc(p.x,p.y,p.z>0?2:1,0,Math.PI*2);ctx.fill()});ctx.globalAlpha=1;ctx.strokeStyle='#ffffff0e';ctx.lineWidth=1;for(let j=0;j<3;j++){ctx.beginPath();ctx.ellipse(cx,cy,s*(1.12+j*.14),s*(.28+j*.08),-.4+j*.25,0,Math.PI*2);ctx.stroke()}ctx.font='9px monospace';ctx.fillStyle='#7c8c9f';ctx.fillText('IDEA / INTELLIGENCE / IMPACT',cx-s*.75,cy+s*1.35)}function loop(){if(!paused&&!document.hidden)draw();requestAnimationFrame(loop)}function motionUI(){document.documentElement.classList.toggle('paused',paused);$('#motion').setAttribute('aria-pressed',String(paused));$('#motion').innerHTML=(paused?'▶':'Ⅱ')+' <span>Motion</span>';$('#motion').title=paused?'Resume animations':'Pause animations'}$('#motion').onclick=()=>{paused=!paused;motionUI()};motionUI();draw();loop();
